INSERT INTO idempotent_record (idempotent_key, biz_type, request_hash, status,
                               locked_until, expire_time)
SELECT #{key}, #{bizType}, #{requestHash}, 0,
       #{lockedUntil}, #{expireTime}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM idempotent_record WHERE idempotent_key = #{key}
)
